# the usual sibling lookup) but excluded from the written output — set only
# through the extension's "remove original field(s)" checkbox on the
# combine/split field creation modal.
HIDDEN_FIELD_NAMES = {
}

# Issue #191: optional Output Blueprint field mapping — ordered
# target-field -> source-field pairs. When set, this replaces
# FIELD_OUTPUT_NAMES for the write-time remap below entirely: the output's
# column names *and order* become this list's own target fields, and any
# source field with no entry here is simply omitted rather than written
